function QuestionsFooter({ remainingSeconds, dispatch, disabled }) {
  const remainingMinutes = Math.floor(remainingSeconds / 60);
  const remainingSecondsInMinute = remainingSeconds % 60;
  return (
    <footer>
      <p class="timer">
        {remainingMinutes}:
        {remainingSecondsInMinute.toString().padStart(2, "0")}
      </p>
      <button
        className="btn btn-ui"
        disabled={disabled}
        onClick={() => dispatch({ type: "QUIT_QUIZ" })}
      >
        Next
      </button>
    </footer>
  );
}

export default QuestionsFooter;
